// Easy version — sort descending, pick index k - 1.
function findKthLargest(nums, k) {
  // Numeric comparator required — bare .sort() coerces to strings.
  nums.sort((a, b) => b - a);
  // After descending sort, the kth largest sits at index k - 1.
  return nums[k - 1];
}
// Time O(n log n), Space O(1) extra.

// OPTIMAL — size-K min-heap (see the p-min-heap lesson for class):
//   const h = new MinHeap();
//   for (const n of nums) { h.push(n); if (h.size() > k) h.pop(); }
//   return h.peek();      // smallest of the K largest = kth largest
// Time O(n log k), Space O(k). Beats sort when k << n.

// Quickselect: pivot + partition + recurse on the side containing k-1.
// Average O(n), worst O(n^2). Interview "wow" answer.

